using ViewportCap.Core;using ViewportCap.Encoding;using Xunit;
namespace ViewportCap.Encoding.Tests;
public sealed class FfmpegExporterTests:IDisposable
{
 private readonly string dir=Path.Combine(Path.GetTempPath(),"viewport-cap-tests",Guid.NewGuid().ToString("N"));
 public FfmpegExporterTests()=>Directory.CreateDirectory(dir);
 public void Dispose(){if(Directory.Exists(dir))Directory.Delete(dir,true);}
 [Fact] public async Task CopySource_CopiesFileWithoutRunningFfmpeg(){var src=Path.Combine(dir,"source.mp4");var output=Path.Combine(dir,"out.mp4");await File.WriteAllTextAsync(src,"video");var runner=new Fake();var exporter=new FfmpegExporter("ffmpeg.exe",new(true,true,true,true),runner);var result=await exporter.ExportAsync(new ExportPlan(Settings(src),output,true),null,CancellationToken.None);Assert.Equal(output,result.OutputPath);Assert.Equal("video",await File.ReadAllTextAsync(output));Assert.Empty(runner.Calls);}
 [Fact] public async Task Transcode_MovesPartialFileIntoPlace(){var src=Path.Combine(dir,"source.mp4");var output=Path.Combine(dir,"out.webm");await File.WriteAllTextAsync(src,"video");var runner=new Fake{OnRun=args=>File.WriteAllText(args[^1],"encoded")};var exporter=new FfmpegExporter("ffmpeg.exe",new(true,true,true,true),runner);var result=await exporter.ExportAsync(new ExportPlan(Settings(src,OutputFormat.WebM),output,false),null,CancellationToken.None);Assert.Equal(output,result.OutputPath);Assert.Equal("encoded",await File.ReadAllTextAsync(output));Assert.False(File.Exists(Path.Combine(dir,"out.partial.webm")));}
 [Fact] public async Task Failure_DeletesPartialFileAndThrows(){var src=Path.Combine(dir,"source.mp4");var output=Path.Combine(dir,"out.webm");await File.WriteAllTextAsync(src,"video");var runner=new Fake{Result=new(1,"","encoder failed"),OnRun=args=>File.WriteAllText(args[^1],"partial")};var exporter=new FfmpegExporter("ffmpeg.exe",new(true,true,true,true),runner);await Assert.ThrowsAsync<ExportException>(()=>exporter.ExportAsync(new ExportPlan(Settings(src,OutputFormat.WebM),output,false),null,CancellationToken.None));Assert.False(File.Exists(Path.Combine(dir,"out.partial.webm")));Assert.False(File.Exists(output));}
 [Fact] public async Task Cancel_WhenPartialIsLocked_StillThrowsCancellation(){var src=Path.Combine(dir,"source.mp4");var output=Path.Combine(dir,"out.webm");await File.WriteAllTextAsync(src,"video");FileStream? locked=null;var runner=new Fake{Throw=new OperationCanceledException(),OnRun=args=>{File.WriteAllText(args[^1],"partial");locked=File.Open(args[^1],FileMode.Open,FileAccess.ReadWrite,FileShare.None);}};var exporter=new FfmpegExporter("ffmpeg.exe",new(true,true,true,true),runner);try{await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>exporter.ExportAsync(new ExportPlan(Settings(src,OutputFormat.WebM),output,false),null,CancellationToken.None));}finally{locked?.Dispose();}}
 [Fact] public async Task CopySource_ReplacesOutputWithoutLeavingPartial(){var src=Path.Combine(dir,"source.mp4");var output=Path.Combine(dir,"out.mp4");await File.WriteAllTextAsync(src,"video");await File.WriteAllTextAsync(output,"old");var exporter=new FfmpegExporter("ffmpeg.exe",new(true,true,true,true),new Fake());await exporter.ExportAsync(new ExportPlan(Settings(src),output,true),null,CancellationToken.None);Assert.Equal("video",await File.ReadAllTextAsync(output));Assert.False(File.Exists(Path.Combine(dir,"out.partial.mp4")));}
 private static ReviewSettings Settings(string src,OutputFormat format=OutputFormat.Mp4)=>new(){SourcePath=src,OutputDirectory=Path.GetDirectoryName(src)!,Format=format,Quality=QualityPreset.Balanced,FrameRate=30,Scale=ScalePreset.Percent100,TrimEnd=TimeSpan.FromSeconds(5),SourceWidth=1280,SourceHeight=720,SourceDuration=TimeSpan.FromSeconds(5)};
 private sealed class Fake:IProcessRunner{public List<IReadOnlyList<string>> Calls{get;}=new();public ProcessResult Result{get;init;}=new(0,"","");public Action<IReadOnlyList<string>>? OnRun{get;init;}public Exception? Throw{get;init;}public Task<ProcessResult> RunAsync(string f,IReadOnlyList<string>a,Action<string>? o,Action<string>? e,CancellationToken c){Calls.Add(a);OnRun?.Invoke(a);return Throw is null?Task.FromResult(Result):Task.FromException<ProcessResult>(Throw);}}
}
